# Gülistan — Birinci ve İkinci Bâb (B1–B2 uyarlama; meşhur beyit ve sözler aslına yakın verilmiştir)
B=[
('باب اول: در سیرت پادشاهان — خواب سلطان محمود','Birinci Bâb: Padişahların sîreti — Sultan Mahmûd’un rüyası',[
('یکی از ملوک خراسان، سلطان محمود سبکتگین را سال‌ها پس از مرگش در خواب دید.','Horasan meliklerinden biri, Sultan Mahmûd-ı Sebüktegin’i ölümünden yıllar sonra rüyasında gördü.'),
('همهٔ وجود او ریخته و خاک شده بود، مگر چشمانش که همچنان در چشمخانه می‌گردید و نظر می‌کرد.','Bütün varlığı dağılmış ve toprak olmuştu; yalnız gözleri hâlâ göz çukurlarında dönüyor ve bakıyordu.'),
('پادشاه از این خواب هراسان برخاست و از حکیمان تعبیر آن را خواست.','Padişah bu rüyadan korkuyla uyandı ve hakîmlerden onun tabirini istedi.'),
('همه درماندند و کسی پاسخی نداد، تا درویشی پیش آمد و زمین ادب بوسید.','Hepsi âciz kaldı ve kimse cevap veremedi; sonunda bir derviş öne çıktı ve edeple yeri öptü.'),
('گفت: «هنوز نگران است که مُلکش با دگران است.»','Dedi ki: “Hâlâ endişeyle bakıyor, çünkü mülkü başkalarının elinde.”'),
('پادشاه مدتی خاموش ماند و در کار جهان اندیشید.','Padişah bir süre sustu ve dünyanın işini düşündü.'),
('بسی نامور زیر زمین دفن کرده‌اند که از هستی‌اش بر روی زمین نشانی نمانده است.','Nice ünlü kişiyi yerin altına gömmüşlerdir ki varlığından yeryüzünde bir iz kalmamıştır.'),
('سعدی می‌گوید: آنچه از آدمی می‌ماند نام نیک است، نه گنج و لشکر و کاخ.','Sa‘dî der ki: İnsandan geriye kalan iyi addır; hazine, ordu ve saray değil.'),
('پس پادشاه دستور داد که از خزانه برای ساختن کاروانسرا و پل و مدرسه هزینه کنند.','Bunun üzerine padişah, hazineden kervansaray, köprü ve medrese yapımı için harcama yapılmasını emretti.')]),
('باب اول — پسر دزدان','Birinci Bâb — Haramilerin oğlu',[
('گروهی از دزدان عرب بر سر کوهی نشسته بودند و راه کاروان‌ها را بسته بودند.','Bir grup Arap haramisi bir dağın tepesine yerleşmiş ve kervanların yolunu kesmişti.'),
('رعیت شهرها از مکر ایشان در امان نبودند و لشکر سلطان نیز از ایشان شکست خورده بود.','Şehirlerin ahalisi onların hilesinden emin değildi; sultanın ordusu da onlara yenilmişti.'),
('سرانجام سپاهیان شبی کمین کردند و هنگامی که دزدان خسته و غنیمت‌گرفته بازگشتند، همه را اسیر گرفتند.','Sonunda askerler bir gece pusu kurdu; haramiler yorgun ve ganimet yüklü döndüklerinde hepsini esir aldılar.'),
('پادشاه فرمان قتل همه را داد. در میان ایشان جوانی بود که میوهٔ عنفوان شبابش نورسیده بود.','Padişah hepsinin öldürülmesini emretti. Aralarında gençliğinin ilk baharında bir delikanlı vardı.'),
('یکی از وزیران زمین بوسید و گفت: «این پسر هنوز از باغ زندگانی بر نخورده است؛ امیدوارم که خداوند او را ببخشد.»','Vezirlerden biri yeri öptü ve dedi ki: “Bu oğlan henüz hayat bağından bir şey tatmadı; umarım efendimiz onu bağışlar.”'),
('پادشاه روی در هم کشید و گفت: «پرتو نیکان نگیرد هر که بنیادش بد است؛ تربیت نااهل را چون گردکان بر گنبد است.»','Padişah yüzünü buruşturdu ve dedi: “Temeli kötü olan iyilerin ışığını almaz; ehil olmayanı terbiye etmek, kubbenin üstüne ceviz koymak gibidir.”'),
('وزیر پاسخ داد: «صحبت نیکان در او اثر خواهد کرد؛ هر فرزندی بر فطرت زاده می‌شود.»','Vezir cevap verdi: “İyilerin sohbeti ona tesir edecektir; her çocuk fıtrat üzere doğar.”'),
('دیگران نیز شفاعت کردند و پادشاه جوان را بخشید، اما گفت: «بخشیدم، هرچند مصلحت ندیدم.»','Diğerleri de şefaat etti ve padişah genci bağışladı, ama dedi ki: “Bağışladım, gerçi doğru bulmadım.”'),
('وزیر پسر را به ناز و نعمت پرورد و استادی ادیب برای تربیت او گماشت.','Vezir oğlanı nimet içinde büyüttü ve terbiyesi için edebiyatçı bir hoca tuttu.'),
('دو سالی گذشت. روزی جوان با گروهی از اوباش محله پیوست و نمک خورد و نمکدان شکست.','İki yıl kadar geçti. Bir gün genç mahallenin serserilerine katıldı; tuzunu yediği yerin tuzluğunu kırdı.'),
('وزیر و دو پسرش را کشت و مال بی‌قیاس برداشت و به مغارهٔ دزدان پدرش رفت.','Veziri ve iki oğlunu öldürdü, ölçüsüz mal aldı ve babasının haramilerinin mağarasına gitti.'),
('پادشاه دست تحیّر به دندان گزید و گفت: «شمشیر نیک از آهن بد چون کند کسی؟»','Padişah hayretle parmağını ısırdı ve dedi: “Kötü demirden iyi kılıcı kim yapabilir?”'),
('سعدی این حکایت را برای نشان دادن قدرت سرشت آورده است؛ اما در باب هفتم، اثر تربیت را نیز می‌ستاید.','Sa‘dî bu hikâyeyi yaratılışın gücünü göstermek için getirmiştir; ama yedinci bâbta terbiyenin tesirini de över.')]),
('باب اول — ستمگر و خواب نیمروز','Birinci Bâb — Zalim ve öğle uykusu',[
('یکی از پادشاهان ستمگر از پارسایی پرسید: «از عبادت‌ها کدام فاضل‌تر است؟»','Zalim padişahlardan biri bir zâhide sordu: “İbadetlerin hangisi daha faziletlidir?”'),
('پارسا گفت: «تو را خواب نیمروز، تا در آن یک نفس خلق را نیازاری.»','Zâhid dedi ki: “Senin için öğle uykusu; tâ ki o bir nefeslik sürede halkı incitmeyesin.”'),
('پادشاه نخست خشمگین شد، اما چون اندیشید، دانست که پارسا راست گفته است.','Padişah önce öfkelendi, ama düşününce zâhidin doğru söylediğini anladı.'),
('سعدی می‌افزاید: ظالمی را خفته دیدم نیمروز؛ گفتم این فتنه است، خوابش برده به.','Sa‘dî ekler: Bir zalimi öğleyin uyurken gördüm; dedim ki bu bir fitnedir, uykuya dalması daha iyi.'),
('آن کس که خوابش بهتر از بیداری است، چنین بدزندگانی، مرده بهتر است.','Uykusu uyanıklığından daha iyi olan kimse için, böyle kötü bir hayat yaşamaktansa ölü olmak daha iyidir.')]),
('باب اول — حجاج و دعای درویش','Birinci Bâb — Haccâc ve dervişin duası',[
('درویشی مستجاب‌الدعوه در بغداد پدید آمد و آوازه‌اش به حجاج بن یوسف رسید.','Bağdat’ta duası kabul olunan bir derviş ortaya çıktı ve şöhreti Haccâc b. Yûsuf’a ulaştı.'),
('حجاج او را بخواند و گفت: «دعای خیری بر من کن.»','Haccâc onu çağırdı ve dedi: “Benim için hayır dua et.”'),
('درویش دست برداشت و گفت: «خدایا، جانش بستان.»','Derviş ellerini kaldırdı ve dedi: “Allahım, canını al.”'),
('حجاج گفت: «از بهر خدای، این چه دعاست؟»','Haccâc dedi: “Allah aşkına, bu nasıl duadır?”'),
('گفت: «این دعای خیر است تو را و جملهٔ مسلمانان را.»','Dedi: “Bu hem senin için hem bütün Müslümanlar için hayır duasıdır.”'),
('زیرا هر روز که زنده بمانی، بر گناهانت افزوده می‌شود و بر رنج مردم نیز.','Çünkü yaşadığın her gün hem günahların artar hem halkın acısı.'),
('ای زبردست زیردست‌آزار، گرم تا کی بماند این بازار؟','Ey güçlü olup güçsüzü inciten, bu pazar ne zamana kadar sıcak kalacak?'),
('به چه کار آیدت جهانداری؟ مردنت به که مردم‌آزاری.','Cihana hükmetmen ne işine yarar? Ölmen, insanları incitmenden daha iyidir.')]),
('باب اول — داریوش و گله‌بان','Birinci Bâb — Dârâ ve at çobanı',[
('دارا، پادشاه عجم، روزی در شکارگاه از لشکر خود جدا افتاد.','Acem padişahı Dârâ bir gün av yerinde ordusundan ayrı düştü.'),
('ناگاه مردی دوان دوان به سوی او آمد. دارا گمان کرد دشمن است و تیر در کمان نهاد.','Birden bir adam koşarak ona doğru geldi. Dârâ düşman sandı ve oku yaya yerleştirdi.'),
('مرد فریاد زد: «ای شاه، من دشمن نیستم؛ گله‌بان اسبان توام و برای خدمت آمده‌ام.»','Adam bağırdı: “Ey şah, ben düşman değilim; atlarının çobanıyım ve hizmet için geldim.”'),
('دارا خندید و گفت: «فرخندهٔ سروش یاریت کرد، وگرنه زه به گوش آورده بودم.»','Dârâ güldü ve dedi: “Kutlu melek sana yardım etti, yoksa kirişi kulağıma kadar çekmiştim.”'),
('گله‌بان گفت: «نصیحت از مُنعِم دریغ نباید داشت.»','Çoban dedi: “Velinimetten öğüt esirgenmemeli.”'),
('«نه تدبیر محمود است و نه رأی صواب که پادشاه دشمن را از دوست باز نشناسد.»','“Padişahın düşmanı dosttan ayırt edememesi ne övülecek bir tedbirdir ne de doğru bir görüş.”'),
('«شرط زندگانی در حضور شاهان آن است که هر کهتری را بشناسند.»','“Şahların huzurunda yaşamanın şartı, her küçüğü tanımalarıdır.”'),
('«تو مرا بارها در حضور دیده‌ای و از اسبان و چراگاه پرسیده‌ای، اکنون که به مهر پیش آمده‌ام، مرا از دشمن باز نمی‌دانی.»','“Sen beni defalarca huzurunda gördün, atları ve otlağı sordun; şimdi sevgiyle önüne gelmişken beni düşmandan ayıramıyorsun.”'),
('«من آن توانم که از صدهزار اسب هر یک را به نام و نشان بشناسم.»','“Bense yüz bin atın her birini adıyla ve işaretiyle tanıyabilirim.”'),
('«مرا گله‌بانی به عقل و تدبیر است؛ تو نیز گلهٔ خویش را نگه دار.»','“Benim çobanlığım akıl ve tedbirledir; sen de kendi sürünü (halkını) koru.”'),
('دارا از سخن او شرمسار شد و فرمود تا او را خلعت دادند.','Dârâ onun sözünden utandı ve ona hil‘at verilmesini emretti.')]),
('باب اول — بنی آدم اعضای یکدیگرند','Birinci Bâb — Âdemoğulları birbirinin âzasıdır',[
('سعدی می‌گوید: در جامع دمشق، بر سر تربت یحیی پیغامبر معتکف بودم.','Sa‘dî der ki: Şam Câmii’nde, Yahyâ peygamberin türbesinin başında itikâftaydım.'),
('یکی از ملوک عرب که به بی‌انصافی معروف بود، به زیارت آمد و نماز گزارد و حاجت خواست.','İnsafsızlıkla tanınan Arap meliklerinden biri ziyarete geldi, namaz kıldı ve dilekte bulundu.'),
('آنگاه روی به من کرد و گفت: «از دشمنی قوی هراسانم؛ در حق من دعا کن.»','Sonra bana döndü ve dedi: “Güçlü bir düşmandan korkuyorum; benim için dua et.”'),
('گفتم: «بر رعیت ضعیف رحمت کن تا از دشمن قوی زحمت نبینی.»','Dedim ki: “Zayıf halkına merhamet et ki güçlü düşmandan sıkıntı görmeyesin.”'),
('«به بازوان توانا و قوّت سردست، خطاست پنجهٔ مسکین ناتوان بشکست.»','“Güçlü kollarla ve bilek kuvvetiyle, çaresiz zavallının pençesini kırmak hatadır.”'),
('«نترسد آن که بر افتادگان نبخشاید؟ که گر ز پای درآید، کسش نگیرد دست.»','“Düşmüşlere acımayan korkmaz mı? Kendisi ayağından düşerse kimse elinden tutmaz.”'),
('سپس این بیت‌ها را خواندم که امروز بر سر در سازمان ملل نوشته شده است:','Sonra şu beyitleri okudum ki bugün Birleşmiş Milletler binasının girişinde yazılıdır:'),
('«بنی آدم اعضای یکدیگرند، که در آفرینش ز یک گوهرند.»','“Âdemoğulları birbirinin âzasıdır; çünkü yaratılışta tek bir cevherdendirler.”'),
('«چو عضوی به درد آورد روزگار، دگر عضوها را نماند قرار.»','“Zaman bir âzayı ağrıtınca, öteki âzaların da huzuru kalmaz.”'),
('«تو کز محنت دیگران بی‌غمی، نشاید که نامت نهند آدمی.»','“Başkalarının derdinden kaygısız olan sen, sana insan adı verilmesi yakışmaz.”')]),
('باب اول — سنگ درویش','Birinci Bâb — Dervişin taşı',[
('ستمگری سنگی بر سر درویشی زد. درویش را مجال انتقام نبود.','Bir zalim bir dervişin başına taş vurdu. Dervişin intikam alacak gücü yoktu.'),
('سنگ را برداشت و نگاه داشت، و سال‌ها آن را در خانه پنهان کرد.','Taşı aldı ve sakladı; yıllarca onu evinde gizledi.'),
('روزگار گذشت تا آنکه پادشاه بر آن ستمگر خشم گرفت و او را در چاهی زندانی کرد.','Zaman geçti; sonunda padişah o zalime öfkelendi ve onu bir kuyuya hapsetti.'),
('درویش آمد و همان سنگ را بر سرش کوفت.','Derviş geldi ve aynı taşı onun başına vurdu.'),
('ستمگر پرسید: «تو کیستی و چرا این سنگ را بر سرم زدی؟»','Zalim sordu: “Sen kimsin ve bu taşı niçin başıma vurdun?”'),
('گفت: «من فلانم و این همان سنگ است که در فلان تاریخ بر سر من زدی.»','Dedi: “Ben falancayım; bu, falan tarihte benim başıma vurduğun taşın ta kendisidir.”'),
('گفت: «این همه روزگار کجا بودی؟» گفت: «از جاهت اندیشه می‌کردم؛ اکنون که در چاهت دیدم، فرصت غنیمت دانستم.»','Dedi: “Bunca zaman neredeydin?” Dedi: “Makamından çekiniyordum; şimdi seni kuyuda görünce fırsatı ganimet bildim.”'),
('سعدی از این حکایت نتیجه می‌گیرد که با بدان در روزگار قدرتشان پنجه نباید کرد، اما روزگار همیشه بر یک حال نمی‌ماند.','Sa‘dî bu hikâyeden şu sonucu çıkarır: Kötülerle güçlü oldukları zamanda pençeleşilmez; ama zaman hep aynı hâlde kalmaz.')]),
('باب اول — نوشیروان و نمک','Birinci Bâb — Nûşirevân ve tuz',[
('آورده‌اند که نوشیروان عادل را در شکارگاهی صیدی کباب می‌کردند و نمک نبود.','Rivayet ederler ki âdil Nûşirevân için bir av yerinde av eti kebap ediyorlardı ve tuz yoktu.'),
('غلامی را به روستا فرستادند تا نمک آورد.','Tuz getirmesi için bir köleyi köye gönderdiler.'),
('نوشیروان گفت: «نمک به قیمت بستان تا رسمی نشود و ده خراب نگردد.»','Nûşirevân dedi: “Tuzu bedeliyle al ki âdet olmasın ve köy harap olmasın.”'),
('گفتند: «از این قدر چه خلل آید؟»','Dediler: “Bu kadarcıktan ne zarar gelir?”'),
('گفت: «بنیاد ظلم در جهان اول اندکی بوده است؛ هر که آمد بر آن مزید کرد تا بدین غایت رسید.»','Dedi: “Zulmün temeli dünyada önce azcıktı; gelen her biri üzerine ekledi, ta ki bu dereceye ulaştı.”'),
('«اگر ز باغ رعیت ملک خورد سیبی، برآورند غلامان او درخت از بیخ.»','“Hükümdar halkın bahçesinden bir elma yerse, köleleri ağacı kökünden söker.”'),
('«به پنج بیضه که سلطان ستم روا دارد، زنند لشکریانش هزار مرغ به سیخ.»','“Sultan beş yumurta için zulmü reva görürse, askerleri bin tavuğu şişe geçirir.”')]),
('باب اول — مژدهٔ مرگ دشمن','Birinci Bâb — Düşmanın ölüm müjdesi',[
('یکی مژده پیش نوشیروان آورد و گفت: «شنیدم که فلان دشمن تو را خدای عزّوجل برداشت.»','Biri Nûşirevân’a müjde getirdi ve dedi: “Duydum ki falan düşmanını Allah (azze ve celle) aldı.”'),
('گفت: «هیچ شنیدی که مرا فروخواهد گذاشت؟»','Dedi: “Beni bırakacağını da hiç duydun mu?”'),
('«اگر بمرد عدو، جای شادمانی نیست؛ که زندگانی ما نیز جاودانی نیست.»','“Düşman öldüyse sevinecek yer yok; çünkü bizim hayatımız da ebedî değil.”'),
('این حکایت کوتاه یکی از عمیق‌ترین درس‌های گلستان است: مرگ دیگری، ما را از مرگ خویش ایمن نمی‌کند.','Bu kısa hikâye Gülistan’ın en derin derslerinden biridir: başkasının ölümü bizi kendi ölümümüzden emin kılmaz.')]),
('باب دوم: در اخلاق درویشان — نماز دوباره','İkinci Bâb: Dervişlerin ahlâkı — Yeniden kılınan namaz',[
('زاهدی مهمان پادشاهی بود. چون به طعام نشستند، کمتر از آن خورد که ارادت او بود.','Bir zâhid bir padişahın misafiriydi. Yemeğe oturduklarında, istediğinden daha az yedi.'),
('و چون به نماز برخاستند، بیش از آن کرد که عادت او بود، تا ظنّ صلاحیت در حقّ او زیادت کنند.','Namaza kalktıklarında da âdetinden fazla kıldı; tâ ki hakkındaki salih zannı artırsınlar.'),
('چون به مقام خویش آمد، سفره خواست تا تناولی کند.','Kendi yerine dönünce yemek bir şeyler atıştırmak için sofra istedi.'),
('پسری صاحب‌فراست داشت؛ گفت: «ای پدر، باری به مجلس سلطان طعام نخوردی؟»','Feraset sahibi bir oğlu vardı; dedi: “Babacığım, sultanın meclisinde yemek yemedin mi?”'),
('گفت: «در نظر ایشان چیزی نخوردم که به کار آید.»','Dedi: “Onların gözü önünde işe yarar bir şey yemedim.”'),
('پسر گفت: «نماز را هم قضا کن که چیزی نکردی که به کار آید.»','Oğul dedi: “Namazı da kaza et; çünkü işe yarar bir şey yapmadın.”'),
('سعدی می‌گوید: ای هنرها نهاده بر کف دست، عیب‌ها را نهفته زیر بغل؛ تا چه خواهی خریدن ای مغرور، روز درماندگی به سیم دغل؟','Sa‘dî der ki: Ey hünerlerini avucunda sergileyip ayıplarını koltuğunun altında gizleyen! Ey mağrur, çaresizlik gününde kalp akçeyle ne satın alacaksın?')]),
('باب دوم — شب‌زنده‌داری و غیبت','İkinci Bâb — Gece ibadeti ve gıybet',[
('سعدی می‌گوید: یاد دارم که در ایام طفولیت متعبّد بودم و شب‌خیز و مولع زهد و پرهیز.','Sa‘dî der ki: Hatırlarım, çocukluk günlerimde ibadete düşkün, gece kalkan ve zühd ile perhize meraklıydım.'),
('شبی در خدمت پدر نشسته بودم و همه شب دیده بر هم نبسته و مصحف عزیز در کنار گرفته.','Bir gece babamın yanında oturmuştum; bütün gece gözümü kırpmamış, aziz Mushaf’ı kucağıma almıştım.'),
('و طایفه‌ای گرد ما خفته بودند.','Bir topluluk da etrafımızda uyuyordu.'),
('پدر را گفتم: «از اینان یکی سر برنمی‌دارد که دوگانه‌ای بگزارد؛ چنان خواب غفلت برده‌اند که گویی نخفته‌اند که مرده‌اند.»','Babama dedim: “Bunlardan biri de başını kaldırıp iki rekât kılmıyor; öyle bir gaflet uykusuna dalmışlar ki sanki uyumuyor, ölmüşler.”'),
('گفت: «جان پدر، تو نیز اگر بخفتی به که در پوستین خلق افتی.»','Dedi: “Babacığım, sen de uyusaydın, halkın kürküne düşmenden (onları çekiştirmenden) daha iyiydi.”'),
('نبیند مدّعی جز خویشتن را، که دارد پردهٔ پندار در پیش.','İddiacı kendinden başkasını görmez, çünkü önünde vehim perdesi vardır.'),
('گرت چشم خدابینی ببخشند، نبینی هیچ کس عاجزتر از خویش.','Sana Allah’ı gören göz bağışlansaydı, kendinden daha âciz kimseyi görmezdin.')]),
('باب دوم — لقمان و ادب','İkinci Bâb — Lokmân ve edep',[
('لقمان را گفتند: «ادب از که آموختی؟»','Lokmân’a dediler: “Edebi kimden öğrendin?”'),
('گفت: «از بی‌ادبان؛ هر چه از ایشان در نظرم ناپسند آمد، از فعل آن پرهیز کردم.»','Dedi: “Edepsizlerden; onların hangi davranışı gözüme çirkin göründüyse, o davranıştan sakındım.”'),
('نگویند از سر بازیچه حرفی، کزان پندی نگیرد صاحب‌هوش.','Şaka yollu bir söz söylemezler ki akıllı kişi ondan bir öğüt almasın.'),
('وگر صد باب حکمت پیش نادان بخوانند، آیدش بازیچه در گوش.','Ama cahilin önünde yüz bâb hikmet okusalar, kulağına oyuncak gibi gelir.')]),
('باب دوم — بانگ مرغ سحر','İkinci Bâb — Seher kuşunun sesi',[
('سعدی می‌گوید: یاد دارم که شبی در کاروانی همه شب رفته بودیم و سحر در کنار بیشه‌ای خفته.','Sa‘dî der ki: Hatırlarım, bir gece bir kervanla bütün gece yürümüş ve seherde bir korunun kenarında uyumuştuk.'),
('شوریده‌ای که در آن سفر همراه ما بود، نعره‌ای برآورد و راه بیابان گرفت و یک نفس آرام نیافت.','O yolculukta bizimle olan bir meczup bir nara attı, çölün yolunu tuttu ve bir an bile huzur bulmadı.'),
('چون روز شد، گفتمش: «آن چه حالت بود؟»','Gün doğunca ona dedim: “O ne hâldi?”'),
('گفت: «بلبلان را دیدم که به نالش درآمده بودند از درخت، و کبکان از کوه، و غوکان در آب، و بهایم از بیشه.»','Dedi: “Bülbülleri ağaçtan, kekliklerin dağdan, kurbağaların sudan, hayvanların korudan inlemeye başladığını gördüm.”'),
('«اندیشه کردم که مروّت نباشد همه در تسبیح و من به غفلت خفته.»','“Düşündüm ki hepsi tesbihte iken benim gaflet içinde uyumam mürüvvet olmaz.”'),
('دوش مرغی به صبح می‌نالید، عقل و صبرم ببرد و طاقت و هوش.','Dün gece bir kuş sabaha karşı inliyordu; aklımı, sabrımı, takatimi ve şuurumu aldı götürdü.'),
('گفت: «باور نداشتم که تو را، بانگ مرغی چنین کند مدهوش.» گفتم: «این شرط آدمیّت نیست؛ مرغ تسبیح‌گوی و من خاموش.»','(Bir dost) dedi: “Bir kuş sesinin seni böyle kendinden geçireceğine inanmazdım.” Dedim: “Bu insanlığın şartı değil; kuş tesbih ediyor, ben susuyorum.”')]),
]
